namespace ROM.Tutorial.Crilium.Editor {
public static class CriliumSceneContent {
 const string Root="Assets/ROM/Tutorial/Crilium/";const string Data=Root+"Resources/Crilium/";
 static T Asset<T>(string path,Func<T> make) where T:UnityEngine.Object {var result=AssetDatabase.LoadAssetAtPath<T>(path);if(!result){result=make();AssetDatabase.CreateAsset(result,path);}return result;}
 static Bounds Bounds(Transform root){var rs=root.GetComponentsInChildren<Renderer>();if(rs.Length==0)return new Bounds(root.position,Vector3.one);var b=rs[0].bounds;foreach(var r in rs)b.Encapsulate(r.bounds);return b;}
 static void Fit(Transform root,float height){var b=Bounds(root);root.localScale*=height/Mathf.Max(.01f,b.size.y);b=Bounds(root);root.position+=Vector3.up*(-b.min.y);}
 static RiftEnemyDefinition Enemy(string name,int hp,int damage,bool dummy,bool boss){
  var source=AssetDatabase.FindAssets("t:RiftEnemyDefinition",new[]{"Assets/ROM/Enemies"}).Select(AssetDatabase.GUIDToAssetPath).Select(AssetDatabase.LoadAssetAtPath<RiftEnemyDefinition>).First(x=>x&&x.Prefab&&x.Id=="little-demon");
  var def=Asset(Data+name+".asset",()=>UnityEngine.Object.Instantiate(source));def.Id="crilium-"+name.ToLowerInvariant();def.DisplayName=dummy?"Eco del pasado":boss?"Centinela de la grieta":"Fragmento hostil";def.Role=dummy?"Objetivo de Crilium":boss?"Guardián de Crilium":"Adversario de Crilium";
  def.Health=hp;def.Damage=damage;def.Experience=def.Gold=0;def.MoveSpeed=dummy?0:boss?2.5f:2.8f;def.Detection=18;def.Leash=32;def.WanderRadius=0;def.CorpseSeconds=3;def.Disposition=dummy?RiftEnemyDisposition.Defensive:RiftEnemyDisposition.Hostile;def.IsBoss=boss;def.IsWildlife=false;def.Skill=dummy?RiftEnemySkill.None:boss?RiftEnemySkill.Slam:RiftEnemySkill.Cleave;def.SkillWindup=boss?1.6f:1.2f;def.SkillCooldown=7;def.SkillMultiplier=1.5f;def.SkillRadius=boss?4.5f:3;def.SkillColor=new Color(.68f,.25f,1);EditorUtility.SetDirty(def);return def;
 }
 [MenuItem("ROM/Crilium/Update own scene content")]
 public static void Configure(){
  if(EditorApplication.isPlayingOrWillChangePlaymode)throw new Exception("Stop Play before editing Crilium");
  Directory.CreateDirectory(Data);AssetDatabase.Refresh();var scene=EditorSceneManager.OpenScene(CriliumSession.ScenePath,OpenSceneMode.Single);
  var terrain=GameObject.Find("Crilium organic route");if(!terrain)throw new Exception("Crilium route missing");
  var dirtPath=AssetDatabase.FindAssets("Dirt_Tiling t:Material",new[]{"Assets/Standard Assets/Sun_Temple"}).Select(AssetDatabase.GUIDToAssetPath).First(x=>Path.GetFileNameWithoutExtension(x)=="Dirt_Tiling");var dirt=AssetDatabase.LoadAssetAtPath<Material>(dirtPath);
  foreach(var space in terrain.transform.Cast<Transform>().Where(t=>t.name.StartsWith("Space "))){
   foreach(var item in space.Cast<Transform>().ToArray()){
    if(item.name=="Walkable foundation"){item.GetComponent<Renderer>().sharedMaterial=dirt;continue;}
    if(item.name.StartsWith("Rock_Boulder")){item.localScale=Vector3.one;Fit(item,7.5f);}
    if(item.name.StartsWith("Fol_TallTree")){item.localScale=Vector3.one;Fit(item,13);}
    if(item.name.StartsWith("Bld_Square_Floor")){item.localScale=Vector3.one;var b=Bounds(item);item.localScale*=18/Mathf.Max(b.size.x,b.size.z);b=Bounds(item);item.position+=Vector3.up*(.035f-b.max.y);}
   }
  }
  var surface=terrain.GetComponent<NavMeshSurface>();if(!surface)surface=terrain.AddComponent<NavMeshSurface>();surface.collectObjects=CollectObjects.Children;surface.useGeometry=NavMeshCollectGeometry.PhysicsColliders;if(!surface.navMeshData)surface.BuildNavMesh();
  if(!surface.navMeshData)throw new Exception("Own Crilium NavMesh bake failed");
  // Keep the bake as a dedicated asset; no original world NavMesh is touched.
  if(string.IsNullOrEmpty(AssetDatabase.GetAssetPath(surface.navMeshData)))AssetDatabase.CreateAsset(surface.navMeshData,Data+"CriliumNavMesh.asset");
  var config=Asset(Data+"Definition.asset",()=>ScriptableObject.CreateInstance<CriliumDefinition>());config.Target=Enemy("Target",5000,1,true,false);config.Enemy=Enemy("Fragment",300,7,false,false);config.Sentinel=Enemy("Sentinel",1800,20,false,true);
  var quest=Asset(Data+"BeforeTheRift.asset",()=>ScriptableObject.CreateInstance<RiftQuestDefinition>());quest.Id=config.QuestId;quest.Title="Antes de la grieta";quest.Description="Este es el poder de Nertör. Cruzá Crilium, conocé tu equipo y enfrentá al centinela que custodia el Rift.";quest.Giver="crilium";quest.TurnIn="crilium-portal";quest.Gold=quest.Experience=0;quest.Objectives=new[]{new JournalObjective{Event=RiftProgressEvent.TrainingHit,Filter="dummy",Label="Conectá un ataque",Required=1},new JournalObjective{Event=RiftProgressEvent.Collect,Filter="crilium-axe",Label="Recogé el hacha de Crilium",Required=1},new JournalObjective{Event=RiftProgressEvent.Kill,Filter="crilium-sentinel",Label="Derrotá al centinela",Required=1}};EditorUtility.SetDirty(quest);
  config.Journal=Asset(Data+"Journal.asset",()=>ScriptableObject.CreateInstance<RiftJournalCatalog>());config.Journal.Quests=new[]{quest};config.Journal.Achievements=Array.Empty<RiftAchievementDefinition>();EditorUtility.SetDirty(config.Journal);
  CriliumLessonDefinition Lesson(CriliumLesson id,string title,string instruction,Vector3 goal,string help)=>new CriliumLessonDefinition{Lesson=id,Title=title,Instruction=instruction,Goal=goal,Help=help};
  Vector3 path=new Vector3(0,0,20),duel=new Vector3(20,0,64),arc=new Vector3(45,0,86),guard=new Vector3(42,0,120),haven=new Vector3(14,0,150),final=new Vector3(0,0,181);
  config.Lessons=new[]{
   Lesson(CriliumLesson.Movement,"Tu camino en Crilium","Avanzá hasta la señal. Usá {Forward} o mantené ambos botones del mouse.",path,"También podés retroceder con {Backward}, girar con {TurnLeft}/{TurnRight} y desplazarte con {StrafeLeft}/{StrafeRight}. El camino se curva, pero siempre vuelve hacia la grieta."),
   Lesson(CriliumLesson.Camera,"Mirá a tu alrededor","Gir á la cámara y ajustá su distancia con la rueda.",new Vector3(0,0,32),"Mantené el botón derecho y mové el mouse para orientar la vista. También podés acercar/alejar con {ZoomIn}/{ZoomOut}. Podés consultar y remapear los controles en Ajustes."),
   Lesson(CriliumLesson.AutoAttack,"Elegí tu objetivo","Seleccioná un eco con clic o {NextTarget}. Conectá dos autoataques ({AutoAttack}).",duel,"Acercate y mirá al objetivo. Clic sobre un enemigo activa el autoataque; {AutoAttack} lo activa/cancela. No hace falta pulsarlo por cada golpe."),
   Lesson(CriliumLesson.Fury,"Generá y gastá Furia","Golpeá para generar Furia. Después conectá una habilidad que la consuma.",duel,"La franja bajo tu vida muestra Furia. Furia cortante y Barrido generan; Rompetierra, Salto y Torbellino consumen. Mirá el coste en su tooltip; gris y barrido radial indican recarga."),
   Lesson(CriliumLesson.Cleave,"Un golpe, tres objetivos","Acercate al grupo y conectá Barrido sobre tres ecos.",arc,"Barrido alcanza hasta tres objetivos visibles del arco frontal. Una roca interrumpe la línea de visión. Reubicarse es mejor que golpear a través del obstáculo."),
   Lesson(CriliumLesson.Mobility,"Controlá la distancia","Usá Salto de guerra para avanzar hacia la siguiente señal.",guard,"Salto usa Furia y tiene recarga propia. Con objetivo, salta hacia él; sin objetivo, avanza según tu orientación. No es necesario apuntar a un enemigo para practicar el desplazamiento."),
   Lesson(CriliumLesson.Defence,"Respondé al peligro","Activá Última resistencia. Probá también Rugido de honor contra el fragmento.",guard,"El área de color anticipa un golpe: salí de ella o usá una defensa. Última resistencia reduce daño; Rugido mejora tu protección y afecta enemigos visibles. Con espada y escudo se activa Maestría del escudo."),
   Lesson(CriliumLesson.Loot,"Una pausa antes del Rift","Entrá al refugio y recogé el hacha del suelo caminando cerca o con clic.",haven,"El brillo y el nombre identifican un objeto recogible. La recogida tiene alcance corto. El equipo de Crilium pertenece únicamente a este prólogo; tu equipo guardado se conserva al salir."),
   Lesson(CriliumLesson.Equipment,"Conocé tu equipo","Abrí la bolsa ({Inventory}), inspeccioná el hacha, equipala y cerrá la bolsa.",haven,"El tooltip muestra daño, velocidad, DPS, nivel, rareza y durabilidad reales. DPS es daño promedio dividido por velocidad. Podés comparar sin perder el control del personaje."),
   Lesson(CriliumLesson.Spellbook,"Tu libro de habilidades","Abrí habilidades ({Abilities}) inspeccioná una habilidad y cerrá el libro.",haven,"Pasá el mouse o usá foco de teclado sobre un icono. El libro explica costes y recargas. Podés arrastrar una habilidad a la barra; las teclas pertenecen a las ranuras."),
   Lesson(CriliumLesson.Talents,"Tu poder completo","Abrí talentos ({Talents}) inspeccioná un nodo y cerrá la pantalla.",haven,"Tus nueve talentos están al máximo en Crilium: es el poder verdadero de Nertör. Armas, Protección y Furia son ramas distintas. Maestría del escudo requiere espada y escudo; podés probar ese equipo aquí."),
   Lesson(CriliumLesson.Journal,"Lo que queda por hacer","Abrí el diario ({Journal}) seguí «Antes de la grieta» y cerralo.",haven,"El diario muestra objetivos y progreso. Seguir una misión actualiza el tracker bajo el minimapa. Un objetivo completado deja de pedir más objetos o bajas."),
   Lesson(CriliumLesson.Map,"Orientate sin perder el camino","Abrí el mapa ({WorldMap}) ubicá tu posición y la señal violeta, y cerralo.",haven,"El minimapa sigue tu posición sin desplazar el HUD. En el mapa, rueda para ampliar y arrastrá para recorrer. La señal violeta apunta al siguiente espacio de Crilium."),
   Lesson(CriliumLesson.Final,"El centinela de la grieta","Derrotá al centinela: combiná ataques, Furia, movilidad y defensa.",final,"El centinela anuncia sus golpes fuertes. Conservá recursos para salir del peligro. Si caés, volvés al último espacio y podés reintentar; no perdés tu progreso guardado."),
   Lesson(CriliumLesson.Portal,"Cruzá el Rift","Entrá en la grieta. Algo al otro lado reclama tu poder.",new Vector3(0,0,194),"El Rift arrebata el poder de Nertör. La aventura continúa recuperándolo. Repetir o saltar este prólogo conserva los niveles, objetos y misiones que ya guardaste en El Rift.")};
  config.Lessons[1].Instruction="Girá la cámara y ajustá su distancia con la rueda.";
  // Literal top-down image of this scene, not the illustrated El Rift map.
  var capture=new GameObject("Crilium atlas capture").AddComponent<Camera>();capture.orthographic=true;capture.orthographicSize=125;capture.aspect=1;capture.transform.position=new Vector3(20,250,100);capture.transform.rotation=Quaternion.Euler(90,0,0);capture.clearFlags=CameraClearFlags.SolidColor;capture.backgroundColor=new Color(.035f,.05f,.075f);capture.nearClipPlane=.1f;capture.farClipPlane=500;
  var rt=new RenderTexture(1024,1024,24);capture.targetTexture=rt;capture.Render();var previous=RenderTexture.active;RenderTexture.active=rt;var texture=new Texture2D(1024,1024,TextureFormat.RGB24,false);texture.ReadPixels(new Rect(0,0,1024,1024),0,0);texture.Apply();File.WriteAllBytes(Data+"CriliumAtlas.png",texture.EncodeToPNG());RenderTexture.active=previous;capture.targetTexture=null;UnityEngine.Object.DestroyImmediate(capture.gameObject);UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(texture);AssetDatabase.ImportAsset(Data+"CriliumAtlas.png");var importer=(TextureImporter)AssetImporter.GetAtPath(Data+"CriliumAtlas.png");importer.wrapMode=TextureWrapMode.Clamp;importer.SaveAndReimport();
  config.Atlas=Asset(Data+"Atlas.asset",()=>ScriptableObject.CreateInstance<RiftMinimapAtlas>());config.Atlas.Map=AssetDatabase.LoadAssetAtPath<Texture2D>(Data+"CriliumAtlas.png");config.Atlas.Center=new Vector2(20,100);config.Atlas.WorldSize=new Vector2(250,250);EditorUtility.SetDirty(config.Atlas);EditorUtility.SetDirty(config);
  var director=UnityEngine.Object.FindFirstObjectByType<CriliumDirector>();director.Definition=config;
  var havenObject=GameObject.Find("Crilium refuge");if(!havenObject)havenObject=new GameObject("Crilium refuge");havenObject.transform.position=haven;var havenPoint=havenObject.GetComponent<RiftCheckpoint>();if(!havenPoint)havenPoint=havenObject.AddComponent<RiftCheckpoint>();havenPoint.Title="Refugio de Crilium";havenPoint.SafeRadius=16;havenPoint.Respawn=havenObject.transform;var horde=UnityEngine.Object.FindFirstObjectByType<ROM.Horde.Horde>();horde.Checkpoints=new[]{horde.defaultSpawnPoints.Spawnpoints[0].GetComponent<RiftCheckpoint>(),havenPoint};
